/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-mosaic> - a composite where every region keeps its own age.
 *
 * For aegis,
 * industrial, machina, vector and terminal. One area drawn from several
 * sensors - radar sites, satellite passes, sonar heads, camera tiles - where
 * each region carries the source it came from and THAT SOURCE'S OWN scan
 * time, and where the parts no source covers are drawn with the REASON they
 * are not covered.
 *
 *   <ov-mosaic label="PRECIPITATION" stale-after="300" expire-after="600">
 *   m.picture = {
 *     compiledAt: t,
 *     sources: [{ id: 'KFWS', at: t - 470000 }, { id: 'KGRK', at: t - 60000 }],
 *     legend: { A: 'KFWS', B: 'KGRK', '#': 'blocked', '~': 'out-of-range' },
 *     grid:   ['AAABBB', 'AA#BBB', '~~#BBB'],
 *     values: ['001230', '002340', '000230'],
 *   };
 *
 * -- THE REFUSAL -----------------------------------------------------------
 *
 * 🔴 A COMPOSITE NEVER CARRIES ONE AGE. The header states the age of the
 * OLDEST CONTRIBUTING PART and names it; the moment the picture was stitched
 * is kept beside it and said, in words, not to be the age of the thing shown.
 * NTSB SA-017, on two fatal accidents: "The age indicator associated with the
 * mosaic image on the cockpit display does not show the age of the actual
 * weather conditions as detected by the NEXRAD network. Instead, the age
 * indicator displays the age of the mosaic image created by the service
 * provider. Weather conditions depicted on the mosaic image will ALWAYS be
 * older than the age indicated on the display." In the Bryan, Texas PA-32 the
 * last three updates "should have each said that they were 1 minute old at the
 * time they were received; however, the actual weather conditions at the time
 * the images were received in the cockpit were about 6, 7, and almost 8
 * minutes old". Garmin names the flaw in its own display (G1000 NXi Pilot's
 * Guide §6.1): a mosaic "is comprised data from multiple radar sites providing
 * data at differing scan rates or intervals ... and assigns one time to this
 * image which becomes the basis of the product age".
 *
 * And four that follow from it:
 *
 * 1. AN AGE NOBODY KNOWS IS NOT AN AGE. If any contributing source has no
 *    scan time, the composite's age is not stated at all: AGE UNKNOWN, with
 *    the unclocked sources named. The oldest part cannot be known when one
 *    part's age is unknown, and the newest known part is not an answer.
 * 2. NOTHING SEEN IS NOT NOTHING THERE, AND THE REASONS ARE NOT ONE REASON.
 *    Garmin draws three different absences in one colour: "Areas where radar
 *    data is not currently available, has not yet been received, or is not
 *    being collected are indicated in gray shade of purple." This element
 *    keeps them apart, and keeps them in two CLASSES, because they answer
 *    different questions: WILL NOT FILL IN (out of range, beam blocked, cone
 *    of silence - geometry, and no amount of waiting changes it) against MAY
 *    FILL IN (site down, not yet received, not selected). FAA AC 00-45H
 *    §3.3.7.2 on blockage: it "appears as a pie-shaped area (or areas)
 *    perpetually void of echoes. When animating the imagery, the beam blockage
 *    area will remain clear of echoes even as precipitation and other targets
 *    pass through."
 * 3. AN EXPIRED PICTURE IS REMOVED, NOT DIMMED AND LEFT UP. Past
 *    `expire-after` the cells go and the age reads dashes. Garmin: "After a
 *    weather product has expired, the system removes the expired weather
 *    product from the displays, and shows white dashes instead of the age."
 * 4. A SOURCE THAT HAS STOPPED DOES NOT KEEP ITS LAST PICTURE. A source
 *    declared down, not selected or awaited contributes NO cells: its whole
 *    territory becomes no-coverage carrying that reason. The failure this
 *    refuses is the one that looks most like weather - a site's last good
 *    echoes left painted on the map while the site is off.
 *
 * A territory older than `stale-after` is marked on the picture and in its
 * row; `stale-after` is never defaulted, and with none declared the element
 * says so rather than judging (SO: NO AGE RULE DECLARED). A composite's age
 * is its oldest part.
 *
 * No `role="img"` on the host: its children would become presentational and
 * the source rows would never be read. The picture is
 * the only aria-hidden part, and every fact drawn in it has a text twin - each
 * source's own age is its row in the list, each absence its row in the gaps
 * list, with cell counts.
 *
 * Drawn on each update and at most once a second while on screen, for ages.
 * Nothing runs every frame.
 *
 * Two reasons are not yet in ov-refusal.js's REASONS: `expired` (past its
 * valid time, removed) and `no-coverage` (no source sees this region).
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';

const LEVELS = 6;            // value classes drawn in a covered cell
const MAX_CELLS = 4000;      // past this the picture is refused, not thinned
const OUTSIDE = '␀';    // the neighbour beyond the edge, for outlining

/* The two classes exist because they answer different questions. `fills`
 * false is geometry: waiting will not change it. */
const COVER = {
  'out-of-range': { word: 'OUT OF RANGE', fills: false },
  blocked: { word: 'BEAM BLOCKED', fills: false },
  cone: { word: 'CONE OF SILENCE', fills: false },
  'site-down': { word: 'SITE DOWN', fills: true },
  awaited: { word: 'NOT YET RECEIVED', fills: true },
  'not-selected': { word: 'NOT SELECTED', fills: true },
};
/* A source's status, when it is not contributing, becomes its territory's
 * reason. `up` is the only status that draws data. */
const STATUS_COVER = { down: 'site-down', awaited: 'awaited', 'not-selected': 'not-selected' };

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const num = (raw) => (raw === null || raw.trim() === '' ? null : Number(raw));
const finite = (v) => v !== null && Number.isFinite(v);
const clock = (ms) => new Date(ms).toTimeString().slice(0, 8);

/* Ages are read at a glance, so they are words, not seconds past a minute. */
function ago(s) {
  const n = Math.max(0, Math.floor(s));
  if (n < 60) return `${n}s`;
  const m = Math.floor(n / 60);
  if (m < 60) return `${m}m ${String(n % 60).padStart(2, '0')}s`;
  return `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m`;
}

let serial = 0;

export class OvMosaic extends HTMLElement {
  static observedAttributes = ['src', 'label', 'stale-after', 'expire-after', 'source'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._pic = null;       // the normalised picture
    this._malformed = 0;
    this._unknownKeys = new Set();
    this._queue = [];
    this._uid = `ov-mosaic-${++serial}`;
    this._probe = null;
    this._said = '';
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.evaluate();
    // Ages move without a new picture: once a second, and only while on screen.
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE. ov-core holds every feed, frame and
    // timer until the first screenful has landed, so the tick is started
    // through whenArrived rather than here; it fires at once on an element
    // upgraded after arrival, which is what lazy loading makes of this one.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.evaluate());
  }

  startTicking() {
    if (this._timer || !this.isConnected) return;
    this._timer = setInterval(() => { if (isSeen(this)) this.evaluate(); }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.evaluate();
  }

  /* A scene from a file, so the element renders as plain markup on a page that
   * carries no script: `<ov-mosaic src="models/mosaic-x.json">`. The same
   * route the kit's other data-driven elements take (ov-consistency,
   * ov-coverage), and the reason a reference page can show one at all.
   *
   * 🔴 A FETCH THAT FAILS LEAVES NO SCENE, NOT A STALE ONE. The element then
   * says what it says with no data, which is its own refusal rather than the
   * last thing that happened to load. The src check after the await is for a
   * src changed while the request was in flight: the loser must not win.
   */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch {
      data = null;
    }
    if (this.getAttribute('src') !== src) return;
    this.picture = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (x) => { this.picture = x; });
  }

  /* ---- taking a picture in ---------------------------------------------- */

  set picture(p) {
    this._malformed = 0;
    this._unknownKeys = new Set();
    this._pic = this.normalise(p);
    this._probe = null;
    this.evaluate();
  }

  get picture() { return this._pic; }

  /* The authored form is a legend plus rows of characters, because a mosaic
   * that cannot be read in the source it is written in cannot be checked. */
  normalise(p) {
    if (!p || typeof p !== 'object' || !Array.isArray(p.grid) || !p.grid.length) return null;
    const legend = p.legend && typeof p.legend === 'object' ? p.legend : {};
    const rows = p.grid.map((r) => String(r));
    const vals = Array.isArray(p.values) ? p.values.map((r) => String(r)) : [];
    const cols = Math.max(...rows.map((r) => r.length));
    const nrows = rows.length;

    // 🔴 A STORED SCENE CANNOT CARRY A WALL-CLOCK TIME. A committed file with
    // an absolute `at` in it reads as years old the week after it is written,
    // so a scene states `ago` in SECONDS BEFORE NOW and the element resolves
    // it against its own clock. `at` still wins where a live feed supplies it.
    const base = OvMosaic.now();
    const when = (x) => {
      if (x.at !== null && x.at !== undefined && Number.isFinite(Number(x.at))) return Number(x.at);
      if (Number.isFinite(Number(x.ago))) return base - Number(x.ago) * 1000;
      return null;
    };
    const sources = new Map();
    for (const s of Array.isArray(p.sources) ? p.sources : []) {
      if (!s || typeof s !== 'object' || s.id === undefined) { this._malformed++; continue; }
      const at = when(s);
      sources.set(String(s.id), {
        id: String(s.id),
        at: Number.isFinite(at) ? at : null,
        dated: Number.isFinite(at),
        status: STATUS_COVER[s.status] ? s.status : 'up',
        cells: 0,
      });
    }

    const cells = [];
    const gaps = new Map();
    for (let y = 0; y < nrows; y++) {
      for (let x = 0; x < cols; x++) {
        const ch = rows[y][x] ?? ' ';
        const v = Number(vals[y]?.[x] ?? 0);
        const cell = { x, y, src: null, cover: null, v: Number.isFinite(v) ? v : 0 };
        const mapped = legend[ch];
        if (mapped === undefined) {
          if (ch !== ' ') this._unknownKeys.add(ch);
          cell.cover = 'not-selected';
        } else if (COVER[mapped]) {
          cell.cover = mapped;
        } else if (sources.has(String(mapped))) {
          const s = sources.get(String(mapped));
          // Refusal 4: a source that is not contributing keeps no territory of
          // data. Its cells become no-coverage carrying its own status.
          if (s.status === 'up') { cell.src = s.id; s.cells++; } else { cell.cover = STATUS_COVER[s.status]; cell.src = s.id; }
        } else {
          // A legend key naming a source nobody declared: the cells exist, and
          // an undeclared source has no scan time, so they are not data.
          this._unknownKeys.add(`${ch} to ${mapped}`);
          cell.cover = 'not-selected';
        }
        if (cell.cover) gaps.set(cell.cover, (gaps.get(cell.cover) || 0) + 1);
        cells.push(cell);
      }
    }

    const compiledAt = when({ at: p.compiledAt, ago: p.compiledAgo });
    return { cols, rows: nrows, cells, gaps, sources, compiledAt };
  }

  /* ---- what the picture is worth ---------------------------------------- */

  evaluate() {
    if (!this._built) return this._report;
    const now = OvMosaic.now();
    const staleAfter = num(this.getAttribute('stale-after'));
    const expireAfter = num(this.getAttribute('expire-after'));
    const pic = this._pic;

    const r = {
      state: 'empty', oldest: null, oldestId: null, ageS: null, compiledS: null,
      undated: [], contributing: [], gaps: [], aged: [], expired: false,
    };

    const done = () => { this._report = r; this.paint(r, staleAfter, expireAfter); this.announce(r); return r; };

    if (!pic) return done();
    if (pic.cols * pic.rows > MAX_CELLS) { r.state = 'overflow'; return done(); }

    r.compiledS = pic.compiledAt === null ? null : (now - pic.compiledAt) / 1000;

    // Refusal 3: expiry is on the PRODUCT, and it removes the product.
    if (finite(expireAfter) && expireAfter > 0 && r.compiledS !== null && r.compiledS > expireAfter) {
      r.state = 'expired';
      r.expired = true;
      return done();
    }

    for (const s of pic.sources.values()) {
      if (s.status !== 'up' || !s.cells) continue;
      r.contributing.push(s);
      if (!s.dated) continue;  // MUTANT: no scan time, no mention
      if (r.oldest === null || s.at < r.oldest) { r.oldest = s.at; r.oldestId = s.id; }
    }

    for (const [reason, n] of pic.gaps) r.gaps.push({ reason, n, ...COVER[reason] });
    r.gaps.sort((a, b) => Number(a.fills) - Number(b.fills) || b.n - a.n);

    if (!r.contributing.length) {
      r.state = 'nothing';          // a picture made entirely of holes
    } else if (r.undated.length) {
      // Refusal 1: the oldest part cannot be known when a part's age is not.
      r.state = 'unknown-age';
    } else {
      r.ageS = (now - r.oldest) / 1000;
      const rule = finite(staleAfter) && staleAfter > 0;
      if (rule) r.aged = r.contributing.filter((s) => (now - s.at) / 1000 > staleAfter).map((s) => s.id);
      r.state = !rule ? 'unruled' : r.aged.length ? 'aged' : 'ok';
    }

    return done();
  }

  get report() { return this._report; }

  /* Announcements from one update are JOINED into one: several writes to a
   * live region in one task are heard as the last only (d7c18ae). */
  say(text) {
    this._queue.push(text);
    if (this._flushing) return;
    this._flushing = true;
    queueMicrotask(() => {
      this._flushing = false;
      const t = this._queue.join('; ');
      this._queue = [];
      const region = this.querySelector('.ov-mosaic__say');
      if (region) { region.textContent = ''; region.textContent = t; }
    });
  }

  /* Only a CHANGE of standing is spoken, and only once per change: an age
   * ticking up is not news every second. */
  announce(r) {
    const key = `${r.state}|${r.aged.join(',')}|${r.gaps.map((g) => g.reason + g.n).join(',')}`;
    if (key === this._said) return;
    const first = this._said === '';
    this._said = key;
    if (first) return;
    if (r.state === 'expired') this.say(`${this.label()} expired and removed`);
    else if (r.state === 'unknown-age') this.say(`${this.label()}: age unknown, ${r.undated.join(', ')} ${r.undated.length > 1 ? 'have' : 'has'} no scan time`);
    else if (r.state === 'nothing') this.say(`${this.label()}: no coverage anywhere`);
    else if (r.aged.length) this.say(`${this.label()}: ${r.aged.join(', ')} older than the age rule`);
  }

  /* ---- drawing ---------------------------------------------------------- */

  label() { return this.getAttribute('label') || 'MOSAIC'; }

  build() {
    this._built = true;
    this.innerHTML = `
      <div class="ov-state ov-state--tag ov-mosaic__age">
        <span class="ov-aside ov-mosaic__label"></span>
        <span class="ov-mosaic__agev"></span>
        <span class="ov-aside ov-mosaic__agewhat"></span>
      </div>
      <div class="ov-aside ov-mosaic__compiled"></div>
      <div class="ov-mosaic__plot" aria-hidden="true">
        <div class="ov-mosaic__grid"></div>
        <svg class="ov-mosaic__edges" preserveAspectRatio="none"></svg>
        <div class="ov-mosaic__tags"></div>
        <div class="ov-mosaic__void" hidden></div>
      </div>
      <div class="ov-aside ov-mosaic__probe"></div>
      <ol class="ov-mosaic__srcs"></ol>
      <ul class="ov-mosaic__gaps"></ul>
      <div class="ov-aside ov-mosaic__rulebox"></div>
      <div class="ov-mosaic__foot"></div>
      <div class="ov-mosaic__say" aria-live="polite"></div>`;
    this.setAttribute('role', 'group');
    const plot = this.querySelector('.ov-mosaic__plot');
    plot.addEventListener('pointermove', (e) => this.pick(e));
    plot.addEventListener('pointerleave', () => { this._probe = null; this.paintProbe(); });
  }

  /* Every region can be asked its own age. The pointer answers for the
   * picture; the source list answers the same question in text. */
  pick(e) {
    const pic = this._pic;
    if (!pic || this._report?.expired) return;
    const box = this.querySelector('.ov-mosaic__grid').getBoundingClientRect();
    if (!box.width || !box.height) return;
    const x = Math.floor(((e.clientX - box.left) / box.width) * pic.cols);
    const y = Math.floor(((e.clientY - box.top) / box.height) * pic.rows);
    if (x < 0 || y < 0 || x >= pic.cols || y >= pic.rows) return;
    this._probe = { x, y };
    this.paintProbe();
  }

  /* Named so a test can ask a region its age without a pointer. */
  ask(x, y) {
    const pic = this._pic;
    if (!pic) return null;
    this._probe = { x, y };
    this.paintProbe();
    return this.querySelector('.ov-mosaic__probe').textContent;
  }

  paintProbe() {
    const el = this.querySelector('.ov-mosaic__probe');
    const pic = this._pic;
    const p = this._probe;
    if (!pic || !p || this._report?.expired) { setText(el, ''); return; }
    const cell = pic.cells[p.y * pic.cols + p.x];
    if (!cell) { setText(el, ''); return; }
    const at = `[${p.x},${p.y}]`;
    if (cell.cover) {
      const c = COVER[cell.cover];
      setText(el, `${at} ${c.word}${cell.src ? ` · ${cell.src}` : ''} · ${c.fills ? 'MAY FILL IN' : 'WILL NOT FILL IN'}`);
      return;
    }
    const s = pic.sources.get(cell.src);
    const age = s?.dated ? `${ago((OvMosaic.now() - s.at) / 1000)} OLD · SCANNED ${clock(s.at)}` : 'NO SCAN TIME';
    setText(el, `${at} ${cell.src} · ${age}`);
  }

  paint(r, staleAfter, expireAfter) {
    const q = (s) => this.querySelector(s);
    const pic = this._pic;
    setText(q('.ov-mosaic__label'), this.label());
    setText(q('.ov-mosaic__rulebox'),
      `STALE ${finite(staleAfter) && staleAfter > 0 ? ago(staleAfter) : 'NO RULE'}`
      + ` · EXPIRES ${finite(expireAfter) && expireAfter > 0 ? ago(expireAfter) : 'NEVER'}`);

    setAttr(this, 'data-ov-state', r.state);
    setAttr(q('.ov-mosaic__age'), 'data-ov-tone',
      r.state === 'ok' ? 'ok' : r.state === 'aged' || r.state === 'unruled' ? 'note' : 'bad');
    const dashed = r.state === 'expired' || r.state === 'unknown-age' || r.state === 'empty' || r.state === 'nothing' || r.state === 'overflow';
    setAttr(this, 'data-ov-refusal',
      r.state === 'expired' ? 'expired'
        : r.state === 'unknown-age' ? 'unknown'
          : r.state === 'nothing' ? 'no-coverage'
            : r.state === 'overflow' ? 'overflow'
              : r.state === 'empty' ? 'unknown' : null);
    setAttr(this, 'data-ov-qualified', r.state === 'aged' ? 'stale' : null);

    // 🔴 The big number is the OLDEST PART, never the compile time.
    setText(q('.ov-mosaic__agev'), dashed ? '—:—' : `${ago(r.ageS)} OLD`);
    const what = r.state === 'expired' ? 'EXPIRED · REMOVED'
      : r.state === 'unknown-age' ? `AGE UNKNOWN · NO SCAN TIME FROM ${r.undated.join(', ')}`
        : r.state === 'nothing' ? 'NO COVERAGE ANYWHERE'
          : r.state === 'overflow' ? 'TOO MANY CELLS FOR THIS DISPLAY'
            : r.state === 'empty' ? 'NO PICTURE'
              : `OLDEST PART · ${r.oldestId}`;
    setText(q('.ov-mosaic__agewhat'), what);
    setAttr(q('.ov-mosaic__agev'), 'data-ov-dashed', dashed ? '' : null);

    // The compile time is kept, and said not to be the age of the thing shown.
    setText(q('.ov-mosaic__compiled'), !pic || r.compiledS === null ? 'IMAGE COMPILE TIME NOT GIVEN'
      : `IMAGE COMPILED ${ago(r.compiledS)} AGO — NOT THE AGE OF WHAT IS DRAWN`);

    this.setAttribute('aria-label', dashed
      ? `${this.label()}: ${what.toLowerCase().replace(/ · /g, ', ')}`
      : `${this.label()}: oldest part ${ago(r.ageS)} old, from ${r.oldestId}, of ${r.contributing.length} sources`);
    setAttr(this, 'data-ov-refusal-text', dashed ? what.toLowerCase() : null);

    this.paintGrid(r, staleAfter);
    this.paintSources(r, staleAfter);
    this.paintGaps(r);
    this.paintProbe();

    const foot = [];
    if (this._unknownKeys.size) foot.push(`${this._unknownKeys.size} legend key${this._unknownKeys.size > 1 ? 's' : ''} named nothing declared: ${[...this._unknownKeys].join(', ')}`);
    if (this._malformed) foot.push(`${this._malformed} malformed source${this._malformed > 1 ? 's' : ''} ignored`);
    setText(q('.ov-mosaic__foot'), foot.join(' · '));
  }

  paintGrid(r, staleAfter) {
    const grid = this.querySelector('.ov-mosaic__grid');
    const edges = this.querySelector('.ov-mosaic__edges');
    const tags = this.querySelector('.ov-mosaic__tags');
    const voidBox = this.querySelector('.ov-mosaic__void');
    const pic = this._pic;

    // Refusal 3: the expired picture is REMOVED, not dimmed and left up.
    const drawable = pic && r.state !== 'expired' && r.state !== 'overflow';
    if (!drawable) {
      if (grid.childElementCount) grid.replaceChildren();
      if (edges.innerHTML) edges.innerHTML = '';
      if (tags.innerHTML) tags.innerHTML = '';
      this._gridKey = null;
      this._edgeD = null;
      voidBox.hidden = false;
      setText(voidBox, r.state === 'expired' ? 'EXPIRED · REMOVED'
        : r.state === 'overflow' ? 'TOO MANY CELLS' : 'NO PICTURE');
      return;
    }
    voidBox.hidden = true;
    setText(voidBox, '');

    const key = `${pic.cols}x${pic.rows}`;
    if (this._gridKey !== key) {
      this._gridKey = key;
      grid.style.setProperty('--ov-mosaic-cols', pic.cols);
      grid.style.setProperty('--ov-mosaic-rows', pic.rows);
      edges.setAttribute('viewBox', `0 0 ${pic.cols} ${pic.rows}`);
      grid.replaceChildren(...pic.cells.map(() => document.createElement('i')));
    }

    const now = OvMosaic.now();
    const rule = finite(staleAfter) && staleAfter > 0;
    const aged = new Set(r.aged);
    pic.cells.forEach((cell, i) => {
      const el = grid.children[i];
      if (!el) return;
      if (cell.cover) {
        setAttr(el, 'data-cover', cell.cover);
        setAttr(el, 'data-fills', COVER[cell.cover].fills ? '' : null);
        setAttr(el, 'data-v', null);
        setAttr(el, 'data-aged', null);
      } else {
        setAttr(el, 'data-cover', null);
        setAttr(el, 'data-fills', null);
        setAttr(el, 'data-v', String(Math.max(0, Math.min(LEVELS - 1, Math.round(cell.v)))));
        setAttr(el, 'data-aged', rule && aged.has(cell.src) ? '' : null);
      }
    });

    // Territory outlines: an internal edge is drawn wherever the two cells
    // either side came from different places. Read once, written once.
    const at = (x, y) => (x < 0 || y < 0 || x >= pic.cols || y >= pic.rows ? null : pic.cells[y * pic.cols + x]);
    const who = (c) => (c ? (c.cover ? `!${c.cover}` : c.src) : OUTSIDE);
    const lines = [];
    for (let y = 0; y < pic.rows; y++) {
      for (let x = 0; x < pic.cols; x++) {
        const me = at(x, y);
        if (who(me) !== who(at(x - 1, y))) lines.push(`M${x} ${y}v1`);
        if (who(me) !== who(at(x, y - 1))) lines.push(`M${x} ${y}h1`);
      }
    }
    lines.push(`M${pic.cols} 0v${pic.rows}`, `M0 ${pic.rows}h${pic.cols}`);
    const d = lines.join('');
    if (this._edgeD !== d) {
      this._edgeD = d;
      edges.innerHTML = `<path d="${d}" vector-effect="non-scaling-stroke"/>`;
    }

    // One tag per territory, at its centroid, placed by %. Words as HTML.
    const cent = new Map();
    for (const cell of pic.cells) {
      if (cell.cover) continue;
      const c = cent.get(cell.src) || { n: 0, x: 0, y: 0 };
      c.n++; c.x += cell.x + 0.5; c.y += cell.y + 0.5;
      cent.set(cell.src, c);
    }
    const html = [...cent].map(([id, c]) => {
      const s = pic.sources.get(id);
      const old = s?.dated && rule && aged.has(id);
      const text = s?.dated ? ago((now - s.at) / 1000) : 'NO TIME';
      return `<span class="ov-mosaic__tag" data-ov-tag="${esc(id)}"${old ? ' data-aged' : ''}${s?.dated ? '' : ' data-undated'}`
        + ` style="left:${((c.x / c.n) / pic.cols) * 100}%;top:${((c.y / c.n) / pic.rows) * 100}%"`
        + `><b>${esc(id)}</b>${esc(text)}</span>`;
    }).join('');
    if (tags.innerHTML !== html) tags.innerHTML = html;
  }

  paintSources(r, staleAfter) {
    const list = this.querySelector('.ov-mosaic__srcs');
    const pic = this._pic;
    const all = pic ? [...pic.sources.values()] : [];
    const key = all.map((s) => s.id).join('|');
    if (this._srcKey !== key) {
      this._srcKey = key;
      list.innerHTML = all.map((s) => `
        <li class="ov-mosaic__src" data-ov-source="${esc(s.id)}">
          <span class="ov-mosaic__sid">${esc(s.id)}</span>
          <span class="ov-mosaic__sage"></span>
          <span class="ov-mosaic__sword"></span>
          <span class="ov-mosaic__scells"></span>
        </li>`).join('');
    }
    const now = OvMosaic.now();
    const rule = finite(staleAfter) && staleAfter > 0;
    const aged = new Set(r.aged);
    const gone = r.state === 'expired';
    all.forEach((s, i) => {
      const li = list.children[i];
      if (!li) return;
      const notUp = s.status !== 'up';
      const word = gone ? 'REMOVED'
        : notUp ? COVER[STATUS_COVER[s.status]].word
          : !s.cells ? 'NO CELLS'
            : !s.dated ? 'NO SCAN TIME'
              : rule && aged.has(s.id) ? 'BEYOND AGE RULE'
                : s.id === r.oldestId ? 'OLDEST PART' : 'CONTRIBUTING';
      setAttr(li, 'data-ov-status', gone ? 'expired' : notUp ? s.status : !s.cells ? 'idle' : !s.dated ? 'undated' : rule && aged.has(s.id) ? 'aged' : 'up');
      // A source that is not contributing has no age worth stating.
      setText(li.querySelector('.ov-mosaic__sage'),
        gone || notUp || !s.cells || !s.dated ? '—' : `${ago((now - s.at) / 1000)} · ${clock(s.at)}`);
      setText(li.querySelector('.ov-mosaic__sword'), word);
      setText(li.querySelector('.ov-mosaic__scells'), gone || notUp || !s.cells ? '0 cells' : `${s.cells} cells`);
    });
  }

  paintGaps(r) {
    const list = this.querySelector('.ov-mosaic__gaps');
    const total = this._pic ? this._pic.cells.length : 0;
    const html = r.state === 'expired' ? '' : r.gaps.map((g) => `
      <li class="ov-mosaic__gap" data-cover="${esc(g.reason)}"${g.fills ? ' data-fills' : ''}>
        <i class="ov-mosaic__swatch" data-cover="${esc(g.reason)}"${g.fills ? ' data-fills' : ''}></i>
        <span class="ov-mosaic__gword">${esc(g.word)}</span>
        <span class="ov-mosaic__gn">${g.n} of ${total}</span>
        <span class="ov-mosaic__gclass">${g.fills ? 'MAY FILL IN' : 'WILL NOT FILL IN'}</span>
      </li>`).join('');
    if (list.innerHTML !== html) list.innerHTML = html;
    setAttr(list, 'hidden', html ? null : '');
  }
}

define('ov-mosaic', OvMosaic);
